from __future__ import annotations

import gc
import sys
import weakref
from pathlib import Path

import polars as pl
import pytest

# the app has no package install: import it from its folder
APP_DIR = Path(__file__).resolve().parents[3] / "experimental" / "reflex-kernel"
sys.path.insert(0, str(APP_DIR))

from reflex_kernel import variables  # noqa: E402
from reflex_kernel.session import Call, Session  # noqa: E402


@pytest.fixture
def session() -> Session:
    return Session()


def frame(rows: int = 3) -> pl.DataFrame:
    return pl.DataFrame({"player": [f"p{n}" for n in range(rows)], "wins": list(range(rows))})


def listed(session: Session, show_all: bool = False) -> list[str]:
    return [row["name"] for row in variables.rows(session, show_all)]


# -- what is listed -------------------------------------------------------------------


def test_data_and_values_are_listed_in_the_order_bound(session: Session) -> None:
    session.bind_result(frame(), "get_head_to_head")
    session.run_python("n = 42\nnames = ['a', 'b']\n_hidden = 1")
    assert listed(session) == ["r1", "n", "names"]
    assert variables.names(session) == ["r1", "n", "names"]


def test_modules_functions_and_classes_only_with_show_all(session: Session) -> None:
    session.run_python("import math\ndef double(x): return x * 2\nclass Thing: pass\nn = 1")
    assert listed(session) == ["n"]
    assert listed(session, show_all=True) == ["math", "double", "Thing", "n"]
    # the names put in up front are never the user's
    assert not {"pl", "db"} & set(listed(session, show_all=True))


def test_a_row_says_what_the_value_is_and_where_it_came_from(session: Session) -> None:
    session.bind_result(frame(5), "get_head_to_head")
    session.run_python("n = 42")
    table, number = variables.rows(session)
    assert (table["type"], table["source"], table["tab"]) == ("DataFrame", "get_head_to_head", "1")
    assert table["shape"] == "5 × 2"  # noqa: RUF001  # the app's own sign for a shape
    assert (number["type"], number["source"], number["tab"]) == ("int", "python", "")
    assert variables.summary(session).startswith("2 names · ")
    # the size as a number too, so a selection can be added up
    assert int(table["bytes"]) > 0


def test_a_closed_tab_is_marked(session: Session) -> None:
    session.bind_result(frame(), "tool")
    session.close_tabs(["r1"])
    assert variables.rows(session)[0]["closed"] == "1"


def test_detail_of_a_table_has_its_columns_inputs_and_aliases(session: Session) -> None:
    session.bind_result(frame(), "get_head_to_head", inputs={"player_1": "MkLeo", "player_2": "Sparg0"})
    session.run_python("same = r1")
    detail = {line["label"]: line["value"] for line in variables.detail(session, "r1")}
    assert detail["from"] == "get_head_to_head"
    assert "MkLeo" in detail["inputs"]
    assert detail["same object as"].startswith("same")
    assert detail["columns"].splitlines() == ["player: String", "wins: Int64"]


def test_detail_of_a_value_is_its_repr_capped(session: Session) -> None:
    session.run_python("text = 'x' * 5000")
    detail = {line["label"]: line["value"] for line in variables.detail(session, "text")}
    assert len(detail["value"]) <= variables.MAX_REPR_CHARS + 1
    assert variables.detail(session, "missing") == []


# -- clearing -------------------------------------------------------------------------


def test_a_cleared_name_is_gone_from_python_with_its_tab(session: Session) -> None:
    session.bind_result(frame(), "tool", inputs={"a": 1}, tool_call_id="call-1")
    session.run_python("n = 42")
    assert session.clear(["r1", "n", "pl", "_", "missing"]) == ["r1", "n"]
    assert "NameError" in session.run_python("r1").error
    assert listed(session) == []
    assert "r1" not in session.tabs()
    assert not session.sources
    assert not session.calls
    assert not session.tool_call_ids
    assert variables.trash_text(session).startswith("Cleared r1, n (")
    assert "pl" in session.namespace


def test_undo_puts_everything_back(session: Session) -> None:
    table = frame()
    session.bind_result(table, "tool", inputs={"a": 1}, tool_call_id="call-1")
    session.clear(["r1"])
    assert session.restore() == []
    assert session.namespace["r1"] is table
    assert session.sources["r1"] == "tool"
    assert session.calls["r1"].inputs == {"a": 1}
    assert session.tool_call_ids["r1"] == "call-1"
    assert not session.trash
    assert variables.trash_text(session) == ""


def test_undo_skips_a_name_bound_again_since(session: Session) -> None:
    session.run_python("a = 1\nb = 2")
    session.clear(["a", "b"])
    session.run_python("a = 'new'")
    assert session.restore() == ["a"]
    assert session.namespace["a"] == "new"
    assert session.namespace["b"] == 2
    assert not session.trash


def test_result_numbers_are_not_given_out_again(session: Session) -> None:
    session.bind_result(frame(), "tool")
    session.bind_result(frame(), "tool")
    session.clear(["r1", "r2"])
    session.purge()
    assert session.bind_result(frame(), "tool") == "r3"


def test_a_purge_frees_the_object(session: Session) -> None:
    session.bind_result(frame(1000), "tool", inputs={"a": 1})
    alive = weakref.ref(session.namespace["r1"])
    session.run_python("r1")  # a cell shows it, and `_` holds it
    session.outputs["c1"] = session.views()["r1"]
    session.clear(["r1"])
    gc.collect()
    assert alive() is not None  # still held, for Undo
    assert session.purge() == ["c1"]
    assert alive() is None
    assert "_" not in session.namespace
    assert not session.outputs
    assert not session.trash
    assert session.freed > 0
    assert variables.trash_text(session).startswith("freed ")
    assert session.restore() == []  # nothing left to put back
    assert "r1" not in session.namespace


def test_the_next_clear_frees_the_batch_before_it(session: Session) -> None:
    session.run_python("a = [1, 2, 3]\nb = 2")
    session.clear(["a"])
    seq = session.trash_seq
    session.clear(["b"])
    assert list(session.trash) == ["b"]
    assert session.trash_seq == seq + 1
    session.restore()
    assert "a" not in session.namespace
    assert session.namespace["b"] == 2


def test_an_object_still_bound_to_another_name_is_kept(session: Session) -> None:
    table = frame()
    session.namespace["r1"] = session.namespace["keep"] = table
    session.outputs["c1"] = session.views()["keep"]
    session.clear(["r1"])
    assert session.purge() == []
    assert session.namespace["keep"] is table
    assert "c1" in session.outputs
    assert session.freed == 0


def test_a_purge_drops_the_agents_original_result_of_a_rerun_form(session: Session) -> None:
    original, rerun = frame(), frame(4)
    session.namespace["r1"], session.namespace["r2"] = original, rerun
    session.calls["r2"] = Call({"a": 2}, rerun, original=({"a": 1}, original), changed=True)
    session.clear(["r1"])
    session.purge()
    assert session.calls["r2"].original is None
